			hint = "Разведайте рудники Элвинна по поручению маршала.",
			text = [=[Донесения из Рудника Подземных Глубин и Яшмовой шахты подтверждают то, чего Дуган опасался. {link:kobolds}Кобольды{/link} больше не досадная помеха, которую можно выгнать факелами. Они расползаются и роют глубже, чем когда-либо осмеливался честный рудокоп.]=],
		},
		{
			title = "Южная граница",
			hint = "Разберитесь с гноллом Дробителем.",
			text = [=[Долгое время рассказы о {link:gnolls}гнолл{/link}е Дробителе считались байками у очага. Дуган перестал считать их байками, когда с южных ферм начали привозить мертвых.]=],
		},
		{
			title = "Сборщик",
			hint = "Проследите путь краденого золота рудников до конца.",
			text = [=[Золотой песок, украденный в рудниках, не остается у {link:kobolds}кобольд{/link}ов. Тайными дорогами он идет к посланцу Братства Справедливости, известному только как Сборщик. Когда находят кольцо Сборщика, на нем оказывается знак старой {link:stonemasons-guild}Гильдии каменщиков{/link} {link:stormwind-city}Штормград{/link}а. Тогда Дуган понимает, что воры {link:elwynn-forest}Элвинн{/link}а — не простые разбойники. Это каменщики, которых Штормград предал.]=],
		},
	},
	mentions = {
