Translate("ruRU", "camping", {
	title = "Походный лагерь",
	sections = {
		{
			title = "Обзор",
			text = [=[Походный лагерь — старое искусство дороги: развести костер в глуши, разделить его с другими и отдохнуть возле него, прежде чем путь продолжится. Путники по всему {link:azeroth}Азерот{/link}у всегда знали, что ночь у хорошего костра может решить, дойдешь ли ты до следующего городка или не дойдешь никогда.]=],
		},
		{
			title = "Костер и ремесла",
			text = [=[Лагерь начинается с костра, который разводят те, кто знает искусство готовки. Затем другие путники могут дополнить его, каждый по своему ремеслу. Кузнец ставит точильный круг. Кожевник поднимает палатку. Алхимик, зачарователь, рудокоп или портной приносит что-то свое: колодец маны, зачарованную лютню, магнитный камень, знамя своего народа. Величайшие из этих творений строятся по чертежам, которые хранят мастера каждого ремесла, и говорят, что некоторые из этих чертежей находятся в руках опасных врагов.]=],
		},
		{
			title = "Обычай костра",
			text = [=[По обычаю каждый путник добавляет к общему костру одно творение, и ни одно ремесло не ставится дважды у одного и того же пламени. Те, кто посидит у такого костра, встают от него отдохнувшими и несут его благо с собой еще многие часы пути.]=],
		},
	},
})
